SELECT QUARTER(stores.opened_date) AS opened_quarter, ROUND(AVG(inventory.quantity), 2) AS avg_quantity, MAX(inventory.quantity) AS max_quantity FROM inventory INNER JOIN products ON inventory.product_id = products.id INNER JOIN stores ON inventory.store_id = stores.id WHERE inventory.quantity BETWEEN 201 AND 230 GROUP BY QUARTER(stores.opened_date) HAVING MAX(inventory.quantity) >= 120;
